    /// marks a forbidden pair. Empty when ENTRIES gives the problem.
    #[inline]
    pub fn DENSE_COST(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(ASGProblem::VT_DENSE_COST, None)}
    }

