impl ::flatbuffers::Verifiable for ASGCandidate<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ASGObjectRef>>("OBJECT", Self::VT_OBJECT, false)?
            .visit_field::<f64>("D2", Self::VT_D2, false)?
            .visit_field::<f64>("P_VALUE", Self::VT_P_VALUE, false)?
            .visit_field::<f64>("POSTERIOR", Self::VT_POSTERIOR, false)?
            .visit_field::<bool>("IN_GATE", Self::VT_IN_GATE, false)?
            .visit_field::<f64>("LOG_DET_S", Self::VT_LOG_DET_S, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("RESIDUAL", Self::VT_RESIDUAL, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("PREDICTED", Self::VT_PREDICTED, false)?
            .visit_field::<f64>("LIGHT_TIME_S", Self::VT_LIGHT_TIME_S, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("POSITION_GCRF_KM", Self::VT_POSITION_GCRF_KM, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("VELOCITY_GCRF_KM_S", Self::VT_VELOCITY_GCRF_KM_S, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("POSITION_COVARIANCE_KM2", Self::VT_POSITION_COVARIANCE_KM2, false)?
            .finish();
        Ok(())
    }
}

