pub struct ASGCandidateBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> ASGCandidateBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_OBJECT(&mut self, OBJECT: ::flatbuffers::WIPOffset<ASGObjectRef<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<ASGObjectRef>>(ASGCandidate::VT_OBJECT, OBJECT);
    }

    #[inline]
    pub fn add_D2(&mut self, D2: f64) {
        self.fbb_.push_slot::<f64>(ASGCandidate::VT_D2, D2, 0.0);
    }

    #[inline]
    pub fn add_P_VALUE(&mut self, P_VALUE: f64) {
        self.fbb_.push_slot::<f64>(ASGCandidate::VT_P_VALUE, P_VALUE, 0.0);
    }

    #[inline]
    pub fn add_POSTERIOR(&mut self, POSTERIOR: f64) {
        self.fbb_.push_slot::<f64>(ASGCandidate::VT_POSTERIOR, POSTERIOR, 0.0);
    }

    #[inline]
    pub fn add_IN_GATE(&mut self, IN_GATE: bool) {
        self.fbb_.push_slot::<bool>(ASGCandidate::VT_IN_GATE, IN_GATE, false);
    }

    #[inline]
    pub fn add_LOG_DET_S(&mut self, LOG_DET_S: f64) {
        self.fbb_.push_slot::<f64>(ASGCandidate::VT_LOG_DET_S, LOG_DET_S, 0.0);
    }

    #[inline]
    pub fn add_RESIDUAL(&mut self, RESIDUAL: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ASGCandidate::VT_RESIDUAL, RESIDUAL);
    }

    #[inline]
    pub fn add_PREDICTED(&mut self, PREDICTED: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ASGCandidate::VT_PREDICTED, PREDICTED);
    }

    #[inline]
    pub fn add_LIGHT_TIME_S(&mut self, LIGHT_TIME_S: f64) {
        self.fbb_.push_slot::<f64>(ASGCandidate::VT_LIGHT_TIME_S, LIGHT_TIME_S, 0.0);
    }

    #[inline]
    pub fn add_POSITION_GCRF_KM(&mut self, POSITION_GCRF_KM: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ASGCandidate::VT_POSITION_GCRF_KM, POSITION_GCRF_KM);
    }

    #[inline]
    pub fn add_VELOCITY_GCRF_KM_S(&mut self, VELOCITY_GCRF_KM_S: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ASGCandidate::VT_VELOCITY_GCRF_KM_S, VELOCITY_GCRF_KM_S);
    }

    #[inline]
    pub fn add_POSITION_COVARIANCE_KM2(&mut self, POSITION_COVARIANCE_KM2: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ASGCandidate::VT_POSITION_COVARIANCE_KM2, POSITION_COVARIANCE_KM2);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> ASGCandidateBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        ASGCandidateBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<ASGCandidate<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

